        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 51425, date: '2025-10-10' }],
  };
  const balance = balanceDue(invoice);
  assert.equal(balance, 0);
});

test('balanceDue calculates remaining balance', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'partially_paid',
    number: 'INV-2025-0001',
    lines: [
      {
        sku: 'DES-HOUR',
